  1	/**
  2	 * At most one Clairic forecast per surface per local day.
  3	 *
  4	 * Each surface (pace, finish, credit) has one meta record holding the day it
  5	 * last asked, what it asked about (`scope`: a folio, an account), and the
  6	 * steps that came back. Same day → the stored answer, even a failed one, so
  7	 * a gateway outage cannot turn into a retry loop. Same day but a different
  8	 * scope → no call; the caller keeps its baseline until tomorrow.
  9	 */
 10	import type { Interval } from "./extraction";
 11	import { loadMetaFromIdb, saveMetaToIdb } from "./idb";
 12	
 13	export type ForecastSurface = "pace" | "finish" | "credit";
 14	
 15	export interface CachedForecast {
 16	  day: string;
 17	  scope: string;
 18	  askedAt: number;
 19	  /** Empty when the call failed or returned nothing usable. */
 20	  steps: Interval[];
 21	}
 22	
 23	export interface ForecastCacheStore {
 24	  load(key: string): Promise<unknown>;
 25	  save(key: string, value: CachedForecast): Promise<void>;
 26	}
 27	
 28	const idbStore: ForecastCacheStore = {
 29	  load: (key) => loadMetaFromIdb(key),
 30	  save: (key, value) => saveMetaToIdb(key, value),
 31	};
 32	
 33	export const forecastCacheKey = (surface: ForecastSurface) =>
 34	  `clairic-forecast:${surface}`;
 35	
 36	function readCached(value: unknown): CachedForecast | null {
 37	  if (!value || typeof value !== "object") return null;
 38	  const v = value as Partial<CachedForecast>;
 39	  if (typeof v.day !== "string" || typeof v.scope !== "string") return null;
 40	  return {
 41	    day: v.day,
 42	    scope: v.scope,
 43	    askedAt: typeof v.askedAt === "number" ? v.askedAt : 0,
 44	    steps: Array.isArray(v.steps) ? v.steps : [],
 45	  };
 46	}
 47	
 48	const inflight = new Map<string, Promise<CachedForecast | null>>();
 49	
 50	/**
 51	 * Today's forecast for `scope`, asking `ask` only if this surface has not
 52	 * asked yet today. Returns null when today's one call went to another scope.
 53	 */
 54	export function dailyForecast(input: {
 55	  surface: ForecastSurface;
 56	  scope: string;
 57	  day: string;
 58	  ask: () => Promise<Interval[]>;
 59	  now?: number;
 60	  store?: ForecastCacheStore;
 61	}): Promise<CachedForecast | null> {
 62	  const store = input.store ?? idbStore;
 63	  const key = forecastCacheKey(input.surface);
 64	  const running = inflight.get(key);
 65	  if (running) return running.then((c) => (c?.scope === input.scope ? c : null));
 66	  const task = (async () => {
 67	    const cached = readCached(await store.load(key));
 68	    if (cached?.day === input.day)
 69	      return cached.scope === input.scope ? cached : null;
 70	    // Claim the day before asking, so a crash mid-call still counts as asked.
 71	    const claim: CachedForecast = {
 72	      day: input.day,
 73	      scope: input.scope,
 74	      askedAt: input.now ?? Date.now(),
 75	      steps: [],
 76	    };
 77	    await store.save(key, claim);
 78	    let steps: Interval[] = [];
 79	    try {
 80	      steps = await input.ask();
 81	    } catch {
 82	      steps = [];
 83	    }
 84	    const done = { ...claim, steps };
 85	    await store.save(key, done);
 86	    return done;
 87	  })();
 88	  inflight.set(key, task);
 89	  void task.finally(() => inflight.delete(key)).catch(() => undefined);
 90	  return task;
 91	}
 92	
 93	/** Read today's record without asking. */
 94	export async function peekForecast(
 95	  surface: ForecastSurface,
 96	  day: string,
 97	  store: ForecastCacheStore = idbStore,
 98	): Promise<CachedForecast | null> {
 99	  const cached = readCached(await store.load(forecastCacheKey(surface)));
100	  return cached?.day === day ? cached : null;
101	}
  1	/**
  2	 * The deterministic half of every forecast Twyne shows.
  3	 *
  4	 * Clairic's forecasts drift toward the average, and with a week of history
  5	 * there is no average worth drifting toward. So each surface is computed here
  6	 * first, from the writer's own numbers, and the model is only allowed to
  7	 * replace it when there is enough history and it lands near this answer
  8	 * (`preferForecast`). Everything is an 80% interval: median, p10, p90.
  9	 */
 10	import type { Interval } from "./extraction";
 11	
 12	/** z for the 10th/90th percentile of a normal. */
 13	const Z80 = 1.2816;
 14	
 15	export function quantile(values: readonly number[], q: number): number {
 16	  if (!values.length) return 0;
 17	  const sorted = [...values].sort((a, b) => a - b);
 18	  const index = Math.min(sorted.length - 1, Math.max(0, (sorted.length - 1) * q));
 19	  const lo = Math.floor(index);
 20	  const hi = Math.ceil(index);
 21	  return sorted[lo] + (sorted[hi] - sorted[lo]) * (index - lo);
 22	}
 23	
 24	export function meanAndSd(values: readonly number[]): { mean: number; sd: number } {
 25	  if (!values.length) return { mean: 0, sd: 0 };
 26	  const mean = values.reduce((a, b) => a + b, 0) / values.length;
 27	  if (values.length < 2) return { mean, sd: 0 };
 28	  const variance =
 29	    values.reduce((sum, v) => sum + (v - mean) ** 2, 0) / (values.length - 1);
 30	  return { mean, sd: Math.sqrt(variance) };
 31	}
 32	
 33	/* ── Today's pace ─────────────────────────────────────────────── */
 34	
 35	export interface PaceHistoryDay {
 36	  /** 0 = Sunday, as `Date#getDay`. */
 37	  weekday: number;
 38	  /** Net words per local hour. */
 39	  hours: number[];
 40	}
 41	
 42	export const PACE_MIN_DAYS = 3;
 43	
 44	/**
 45	 * Words the writer will finish today with, from what they usually add after
 46	 * this point in the day.
 47	 *
 48	 * Conditioned on writing days only: the line only shows once today has
 49	 * begun, so the question is "on days like this, how much more came?". Uses
 50	 * the same weekday when there are three of them, every writing day
 51	 * otherwise. The interval is the empirical spread of those days' remainders.
 52	 */
 53	export function paceBaseline(input: {
 54	  history: readonly PaceHistoryDay[];
 55	  weekday: number;
 56	  /** Fractional local hour now, e.g. 14.5 at half past two. */
 57	  hourNow: number;
 58	  wordsSoFar: number;
 59	}): (Interval & { days: number }) | null {
 60	  const writing = input.history.filter((d) =>
 61	    d.hours.some((n) => n > 0),
 62	  );
 63	  if (writing.length < PACE_MIN_DAYS) return null;
 64	  const sameDay = writing.filter((d) => d.weekday === input.weekday);
 65	  const pool = sameDay.length >= PACE_MIN_DAYS ? sameDay : writing;
 66	  const hour = Math.min(23, Math.max(0, Math.floor(input.hourNow)));
 67	  const left = 1 - (input.hourNow - hour);
 68	  const remainders = pool.map((d) => {
 69	    let rest = Math.max(0, d.hours[hour] ?? 0) * left;
 70	    for (let h = hour + 1; h < 24; h++) rest += Math.max(0, d.hours[h] ?? 0);
 71	    return rest;
 72	  });
 73	  const base = Math.max(0, input.wordsSoFar);
 74	  return {
 75	    median: base + quantile(remainders, 0.5),
 76	    p10: base + quantile(remainders, 0.1),
 77	    p90: base + quantile(remainders, 0.9),
 78	    days: pool.length,
 79	  };
 80	}
 81	
 82	/* ── Reaching a total: draft length, or spending a balance ───────── */
 83	
 84	/**
 85	 * Days until a running sum of daily increments reaches `remaining`, as an
 86	 * interval. Treats days as independent draws with the observed mean and
 87	 * spread, so after `d` days the sum is ~N(d·m, d·s²); solving
 88	 * d·m ± z·s·√d = remaining for √d gives the early and late crossings.
 89	 * Null when the pace is not moving toward the total at all.
 90	 */
 91	export function daysToReach(
 92	  dailyIncrements: readonly number[],
 93	  remaining: number,
 94	  minDays = PACE_MIN_DAYS,
 95	): Interval | null {
 96	  if (remaining <= 0) return { median: 0, p10: 0, p90: 0 };
 97	  if (dailyIncrements.length < minDays) return null;
 98	  const { mean, sd } = meanAndSd(dailyIncrements);
 99	  if (mean <= 0) return null;
100	  const root = (sign: 1 | -1) => {
101	    const b = sign * Z80 * sd;
102	    const x = (-b + Math.sqrt(b * b + 4 * mean * remaining)) / (2 * mean);
103	    return x * x;
104	  };
105	  return {
106	    median: remaining / mean,
107	    p10: root(1),
108	    p90: root(-1),
109	  };
110	}
111	
112	/* ── This month's hosted spend ─────────────────────────────────── */
113	
114	export interface DailyAmount {
115	  weekday: number;
116	  amount: number;
117	}
118	
119	/**
120	 * Total for a period given what is already spent and the days still to
121	 * come. Weekday-aware once each weekday has been seen three times (writers
122	 * often have a heavy day); a flat trailing mean before that. The interval
123	 * comes from the residuals of that model, widened by √days.
124	 */
125	export function periodTotalBaseline(input: {
126	  history: readonly DailyAmount[];
127	  spentSoFar: number;
128	  /** Weekdays of the days left in the period, today's remainder excluded. */
129	  upcoming: readonly number[];
130	}): Interval | null {
131	  if (input.history.length < PACE_MIN_DAYS) return null;
132	  const byWeekday = new Map<number, number[]>();
133	  for (const d of input.history)
134	    byWeekday.set(d.weekday, [...(byWeekday.get(d.weekday) ?? []), d.amount]);
135	  const weekdayAware = [...Array(7).keys()].every(
136	    (w) => (byWeekday.get(w)?.length ?? 0) >= 3,
137	  );
138	  const overall = meanAndSd(input.history.map((d) => d.amount)).mean;
139	  const expected = (weekday: number) =>
140	    weekdayAware ? meanAndSd(byWeekday.get(weekday)!).mean : overall;
141	  const residuals = input.history.map((d) => d.amount - expected(d.weekday));
142	  const sd = meanAndSd(residuals).sd;
143	  const ahead = input.upcoming.reduce((sum, w) => sum + expected(w), 0);
144	  const spread = Z80 * sd * Math.sqrt(input.upcoming.length);
145	  const median = input.spentSoFar + ahead;
146	  return {
147	    median,
148	    p10: Math.max(input.spentSoFar, median - spread),
149	    p90: median + spread,
150	  };
151	}
152	
153	/* ── Model vs baseline ──────────────────────────────────────────── */
154	
155	/**
156	 * Take the model's interval only when history is long enough to trust it
157	 * and its median sits within the baseline's band widened by half its width
158	 * on each side (never less than 15% of the baseline median, so a perfectly
159	 * steady record does not shut the model out entirely). Otherwise the baseline stands: a model answer far from the
160	 * writer's own record is the drift-to-average failure, not insight.
161	 */
162	export function preferForecast(
163	  baseline: Interval | null,
164	  model: Interval | null,
165	  enoughHistory: boolean,
166	): { value: Interval; source: "baseline" | "clairic" } | null {
167	  if (!baseline) return null;
168	  if (!model || !enoughHistory) return { value: baseline, source: "baseline" };
169	  const half = Math.max(
170	    (baseline.p90 - baseline.p10) / 2,
171	    Math.abs(baseline.median) * 0.15,
172	    1e-9,
173	  );
174	  const ok =
175	    model.median >= baseline.p10 - half &&
176	    model.median <= baseline.p90 + half &&
177	    model.p10 <= model.median &&
178	    model.median <= model.p90;
179	  return ok
180	    ? { value: model, source: "clairic" }
181	    : { value: baseline, source: "baseline" };
182	}
183	
184	/**
185	 * Steps of a per-day (or per-hour) forecast, summed until they cover
186	 * `remaining`. Returns the 1-based step index where the median, the fast
187	 * edge (p90 increments) and the slow edge (p10 increments) cross, or null
188	 * when the median never crosses inside the horizon. A slow edge that never
189	 * crosses is reported at the horizon's end + 1 so the caller can see it.
190	 */
191	export function stepsToReach(
192	  steps: readonly Interval[],
193	  remaining: number,
194	): Interval | null {
195	  if (remaining <= 0) return { median: 0, p10: 0, p90: 0 };
196	  const cross = (pick: (s: Interval) => number) => {
197	    let sum = 0;
198	    for (let i = 0; i < steps.length; i++) {
199	      sum += Math.max(0, pick(steps[i]));
200	      if (sum >= remaining) return i + 1;
201	    }
202	    return null;
203	  };
204	  const median = cross((s) => s.median);
205	  if (median === null) return null;
206	  return {
207	    median,
208	    p10: cross((s) => s.p90) ?? median,
209	    p90: cross((s) => s.p10) ?? steps.length + 1,
210	  };
211	}
212	
213	/** Sum of step intervals: a loose but honest bound on a total. */
214	export function sumSteps(steps: readonly Interval[]): Interval {
215	  return steps.reduce(
216	    (acc, s) => ({
217	      median: acc.median + s.median,
218	      p10: acc.p10 + s.p10,
219	      p90: acc.p90 + s.p90,
220	    }),
221	    { median: 0, p10: 0, p90: 0 },
222	  );
223	}

  1	/**
  2	 * The three forecasts the writer sees — today's pace, when the draft is
  3	 * done, and how long hosted credit lasts — each a baseline from
  4	 * `forecast-baselines`, optionally replaced by one Clairic forecast a day.
  5	 *
  6	 * Nothing here renders. Callers get a median and an 80% interval, or null
  7	 * when there is nothing honest to say yet.
  8	 */
  9	import type { ConvexClient } from "convex/browser";
 10	import type { ProjectBrief } from "../types";
 11	import {
 12	  forecast,
 13	  forecastSteps,
 14	  type ExtractionRequest,
 15	  type ExtractionResult,
 16	  type Interval,
 17	} from "./extraction";
 18	import { askExtraction } from "./extraction-client";
 19	import {
 20	  daysToReach,
 21	  paceBaseline,
 22	  periodTotalBaseline,
 23	  preferForecast,
 24	  stepsToReach,
 25	  sumSteps,
 26	  type DailyAmount,
 27	  type PaceHistoryDay,
 28	} from "./forecast-baselines";
 29	import { dailyForecast, type ForecastCacheStore } from "./forecast-cache";
 30	import {
 31	  addDays,
 32	  dayToTime,
 33	  dayTotal,
 34	  folioDailyGains,
 35	  localDay,
 36	  type PaceLedger,
 37	} from "./writing-pace-ledger";
 38	
 39	/** Days of history before Clairic is asked at all. */
 40	export const MODEL_MIN_DAYS = 14;
 41	/** Below this many words today, a pace line is noise. */
 42	export const PACE_MIN_WORDS_TODAY = 50;
 43	const HISTORY_DAYS = 28;
 44	const FINISH_HORIZON_DAYS = 60;
 45	const CREDIT_HORIZON_DAYS = 45;
 46	
 47	export type ForecastSource = "baseline" | "clairic";
 48	
 49	/** Development only: inject `{ pace, finish, credit, hosted }` for browser checks. */
 50	export const FORECAST_PREVIEW_EVENT = "twyne:forecast-preview";
 51	
 52	type Ask = (request: ExtractionRequest) => Promise<ExtractionResult>;
 53	
 54	interface ModelOptions {
 55	  /** Absent → baseline only. */
 56	  ask?: Ask;
 57	  store?: ForecastCacheStore;
 58	}
 59	
 60	export function clientAsk(client: ConvexClient | null | undefined): Ask | undefined {
 61	  return client ? (request) => askExtraction(client, request) : undefined;
 62	}
 63	
 64	const WEEKDAYS = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
 65	const weekdayOf = (day: string) => new Date(dayToTime(day)).getDay();
 66	
 67	async function stepsFrom(
 68	  ask: Ask,
 69	  request: ExtractionRequest,
 70	): Promise<Interval[]> {
 71	  const result = await ask(request);
 72	  return result.ok ? forecastSteps(result.answers?.next) : [];
 73	}
