 75	/* ── Today's pace ─────────────────────────────────────────────── */
 76	
 77	export interface PaceForecast extends Interval {
 78	  wordsSoFar: number;
 79	  source: ForecastSource;
 80	}
 81	
 82	export function paceHistory(ledger: PaceLedger, today: string): PaceHistoryDay[] {
 83	  const out: PaceHistoryDay[] = [];
 84	  for (let i = HISTORY_DAYS; i >= 1; i--) {
 85	    const key = addDays(today, -i);
 86	    const day = ledger.days[key];
 87	    if (day) out.push({ weekday: weekdayOf(key), hours: day.hours });
 88	  }
 89	  return out;
 90	}
 91	
 92	export async function paceForecast(
 93	  ledger: PaceLedger,
 94	  now: number,
 95	  options: ModelOptions = {},
 96	): Promise<PaceForecast | null> {
 97	  const today = localDay(now);
 98	  const wordsSoFar = Math.max(0, dayTotal(ledger.days[today]));
 99	  if (wordsSoFar < PACE_MIN_WORDS_TODAY) return null;
100	  const date = new Date(now);
101	  const hourNow = date.getHours() + date.getMinutes() / 60;
102	  const history = paceHistory(ledger, today);
103	  const baseline = paceBaseline({
104	    history,
105	    weekday: date.getDay(),
106	    hourNow,
107	    wordsSoFar,
108	  });
109	  if (!baseline) return null;
110	
111	  const writingDays = history.filter((d) => d.hours.some((n) => n > 0)).length;
112	  const enough = writingDays >= MODEL_MIN_DAYS;
113	  let model: Interval | null = null;
114	  if (enough && options.ask) {
115	    const ask = options.ask;
116	    const startHour = date.getHours();
117	    const cached = await dailyForecast({
118	      surface: "pace",
119	      scope: "all",
120	      day: today,
121	      now,
122	      store: options.store,
123	      ask: () =>
124	        stepsFrom(ask, {
125	          state: paceState(ledger, today, startHour),
126	          reference_date: today,
127	          fields: {
128	            next: forecast(
129	              "Net words this writer will write in each remaining hour of today, from their hourly history.",
130	              { min: 0, max: 3_000, horizon: 24 - startHour, interval: "hour" },
131	            ),
132	          },
133	        }),
134	    });
135	    if (cached?.steps.length) {
136	      // The steps begin at the hour of the day's one call; drop the past.
137	      const askedHour = new Date(cached.askedAt).getHours();
138	      const offset = date.getHours() - askedHour;
139	      const ahead = cached.steps.slice(Math.max(0, offset));
140	      if (ahead.length) {
141	        const left = 1 - date.getMinutes() / 60;
142	        const rest = sumSteps([
143	          { ...scale(ahead[0], left) },
144	          ...ahead.slice(1),
145	        ]);
146	        model = {
147	          median: wordsSoFar + rest.median,
148	          p10: wordsSoFar + rest.p10,
149	          p90: wordsSoFar + rest.p90,
150	        };
151	      }
152	    }
153	  }
154	  const chosen = preferForecast(baseline, model, enough)!;
155	  return { ...chosen.value, wordsSoFar, source: chosen.source };
156	}
157	
158	const scale = (s: Interval, k: number): Interval => ({
159	  median: s.median * k,
160	  p10: s.p10 * k,
161	  p90: s.p90 * k,
162	});
163	
164	function paceState(ledger: PaceLedger, today: string, hour: number): string {
165	  const lines = ["Net words written per local hour (00–23), recent days:"];
166	  for (let i = HISTORY_DAYS; i >= 1; i--) {
167	    const key = addDays(today, -i);
168	    const day = ledger.days[key];
169	    if (!day) continue;
170	    lines.push(`${key} ${WEEKDAYS[weekdayOf(key)]}: ${day.hours.map(Math.round).join(",")}`);
171	  }
172	  const todays = ledger.days[today]?.hours.slice(0, hour) ?? [];
173	  lines.push(
174	    `Today ${today} ${WEEKDAYS[weekdayOf(today)]}, hours 00–${String(hour - 1).padStart(2, "0")}: ${todays.map(Math.round).join(",")}`,
175	    `Forecast hours ${String(hour).padStart(2, "0")}–23.`,
176	  );
177	  return lines.join("\n");
178	}
