180	/* ── Draft finish ─────────────────────────────────────────────── */
181	
182	/**
183	 * The writer's stated length, if the brief states one in words. Pages and
184	 * "a chapter" are left alone: turning those into a word count would be
185	 * inventing a target. A range resolves to its lower end — the draft is
186	 * long enough once it is inside the range.
187	 */
188	export function briefWordTarget(brief: ProjectBrief | null | undefined): number | null {
189	  if (!brief) return null;
190	  const text = [
191	    brief.answers.format,
192	    brief.answers.constraints,
193	    ...(brief.probes ?? [])
194	      .filter((p) => p.relatesTo === "format" || p.relatesTo === "constraints")
195	      .map((p) => (Array.isArray(p.answer) ? p.answer.join(" ") : String(p.answer ?? ""))),
196	  ].join(" \n ");
197	  const number = String.raw`(\d{1,3}(?:[,  ]\d{3})+|\d+(?:\.\d+)?)\s*(k)?`;
198	  const match = new RegExp(
199	    String.raw`(?:${number})\s*(?:(?:-|–|—|to)\s*(?:${number})\s*)?(?:words?|wds)\b`,
200	    "i",
201	  ).exec(text);
202	  if (!match) return null;
203	  const value = (raw: string, k?: string) =>
204	    Number(raw.replace(/[,  ]/g, "")) * (k ? 1_000 : 1);
205	  // "3–5k words": the k on the upper end applies to a bare lower one.
206	  const sharedK = !match[2] && match[4] && Number(match[1]) < 1_000;
207	  const low = value(match[1], match[2] ?? (sharedK ? "k" : undefined));
208	  if (!Number.isFinite(low) || low < 100 || low > 500_000) return null;
209	  return Math.round(low);
210	}
211	
212	export interface FinishForecast {
213	  target: number;
214	  current: number;
215	  /** Local day keys. */
216	  median: string;
217	  early: string;
218	  late: string;
219	  source: ForecastSource;
220	}
221	
222	export async function finishForecast(input: {
223	  ledger: PaceLedger;
224	  folioId: string;
225	  currentWords: number;
226	  target: number | null;
227	  now: number;
228	  options?: ModelOptions;
229	}): Promise<FinishForecast | null> {
230	  const { target, currentWords } = input;
231	  if (!target || currentWords >= target) return null;
232	  const today = localDay(input.now);
233	  const { gains, observedDays } = folioDailyGains(
234	    input.ledger,
235	    input.folioId,
236	    today,
237	    HISTORY_DAYS,
238	  );
239	  // Today is still being written; judge the pace on finished days.
240	  const finished = gains.slice(0, -1);
241	  const remaining = target - currentWords;
242	  const baseline = daysToReach(finished, remaining);
243	  if (!baseline || baseline.median > 366) return null;
244	
245	  const enough = observedDays - 1 >= MODEL_MIN_DAYS;
246	  let model: Interval | null = null;
247	  const ask = input.options?.ask;
248	  if (enough && ask) {
249	    const cached = await dailyForecast({
250	      surface: "finish",
251	      scope: input.folioId,
252	      day: today,
253	      now: input.now,
254	      store: input.options?.store,
255	      ask: () =>
256	        stepsFrom(ask, {
257	          state: [
258	            "Net words added to one draft per day, oldest first:",
259	            ...finished.map(
260	              (n, i) =>
261	                `${addDays(today, i - finished.length)} ${WEEKDAYS[weekdayOf(addDays(today, i - finished.length))]}: ${Math.round(n)}`,
262	            ),
263	            `Draft is ${currentWords} words; target ${target}.`,
264	          ].join("\n"),
265	          reference_date: today,
266	          fields: {
267	            next: forecast(
268	              "Net words this writer will add to the draft on each coming day, starting today.",
269	              { min: 0, max: 10_000, horizon: FINISH_HORIZON_DAYS, interval: "day" },
270	            ),
271	          },
272	        }),
273	    });
274	    // Step n covers day n-1 (today is step 1): convert to days from today.
275	    const crossing = cached?.steps.length
276	      ? stepsToReach(cached.steps, remaining)
277	      : null;
278	    if (crossing)
279	      model = {
280	        median: crossing.median - 1,
281	        p10: crossing.p10 - 1,
282	        p90: crossing.p90 - 1,
283	      };
284	  }
285	  const chosen = preferForecast(baseline, model, enough)!;
286	  const day = (n: number) => addDays(today, Math.max(0, Math.ceil(n)));
287	  return {
288	    target,
289	    current: currentWords,
290	    median: day(chosen.value.median),
291	    early: day(chosen.value.p10),
292	    late: day(chosen.value.p90),
293	    source: chosen.source,
294	  };
295	}
