297	/* ── Hosted credit ─────────────────────────────────────────────── */
298	
299	export interface HostedSpendDay {
300	  /** Local day key. */
301	  day: string;
302	  micros: number;
303	}
304	
305	export interface CreditForecast {
306	  /** This month's projected total spend, micro-USD. */
307	  month: Interval;
308	  spentMicros: number;
309	  availableMicros: number;
310	  /** Local day keys when credit runs out, or null when it outlasts the horizon. */
311	  runsOut: { median: string; early: string; late: string } | null;
312	  /** True when even the slow edge lands before month end. */
313	  outlastsMonth: boolean;
314	  monthEnd: string;
315	  source: ForecastSource;
316	}
317	
318	/** Group hosted ledger charges into local days, filling gaps with zero. */
319	export function dailyHostedSpend(
320	  events: readonly { occurredAt: number; source: string; costMicrousd?: number }[],
321	  today: string,
322	  span = HISTORY_DAYS,
323	): HostedSpendDay[] {
324	  const totals = new Map<string, number>();
325	  for (const e of events) {
326	    if (e.source !== "hosted" || !e.costMicrousd) continue;
327	    const key = localDay(e.occurredAt);
328	    totals.set(key, (totals.get(key) ?? 0) + e.costMicrousd);
329	  }
330	  const first = [...totals.keys()].sort()[0];
331	  if (!first) return [];
332	  const out: HostedSpendDay[] = [];
333	  for (let i = span; i >= 1; i--) {
334	    const key = addDays(today, -i);
335	    if (key >= first) out.push({ day: key, micros: totals.get(key) ?? 0 });
336	  }
337	  return out;
338	}
339	
340	export function monthEndDay(today: string): string {
341	  const d = new Date(dayToTime(today));
342	  return localDay(new Date(d.getFullYear(), d.getMonth() + 1, 0, 12).getTime());
343	}
344	
345	export async function creditForecast(input: {
346	  history: readonly HostedSpendDay[];
347	  spentMicros: number;
348	  availableMicros: number;
349	  now: number;
350	  scope: string;
351	  options?: ModelOptions;
352	}): Promise<CreditForecast | null> {
353	  const today = localDay(input.now);
354	  const monthEnd = monthEndDay(today);
355	  const upcoming: number[] = [];
356	  for (let d = addDays(today, 1); d <= monthEnd; d = addDays(d, 1))
357	    upcoming.push(weekdayOf(d));
358	  const daily: DailyAmount[] = input.history.map((h) => ({
359	    weekday: weekdayOf(h.day),
360	    amount: h.micros,
361	  }));
362	  const monthBase = periodTotalBaseline({
363	    history: daily,
364	    spentSoFar: input.spentMicros,
365	    upcoming,
366	  });
367	  if (!monthBase) return null;
368	  const runBase = daysToReach(
369	    daily.map((d) => d.amount),
370	    input.availableMicros,
371	  );
372	
373	  const spendDays = input.history.filter((h) => h.micros > 0).length;
374	  const enough = spendDays >= MODEL_MIN_DAYS;
375	  let monthModel: Interval | null = null;
376	  let runModel: Interval | null = null;
377	  const ask = input.options?.ask;
378	  if (enough && ask) {
379	    const cached = await dailyForecast({
380	      surface: "credit",
381	      scope: input.scope,
382	      day: today,
383	      now: input.now,
384	      store: input.options?.store,
385	      ask: () =>
386	        stepsFrom(ask, {
387	          state: [
388	            "Hosted AI spend per day in US dollars, oldest first:",
389	            ...input.history.map(
390	              (h) => `${h.day} ${WEEKDAYS[weekdayOf(h.day)]}: ${(h.micros / 1e6).toFixed(4)}`,
391	            ),
392	          ].join("\n"),
393	          reference_date: today,
394	          fields: {
395	            next: forecast(
396	              "Hosted AI spend in US dollars on each coming day, starting tomorrow.",
397	              { min: 0, max: 20, horizon: CREDIT_HORIZON_DAYS, interval: "day" },
398	            ),
399	          },
400	        }),
401	    });
402	    const steps = (cached?.steps ?? []).map((s) => scale(s, 1e6));
403	    if (steps.length) {
404	      const inMonth = sumSteps(steps.slice(0, upcoming.length));
405	      monthModel = {
406	        median: input.spentMicros + inMonth.median,
407	        p10: input.spentMicros + inMonth.p10,
408	        p90: input.spentMicros + inMonth.p90,
409	      };
410	      runModel = stepsToReach(steps, input.availableMicros);
411	    }
412	  }
413	  const month = preferForecast(monthBase, monthModel, enough)!;
414	  const run = preferForecast(runBase, runModel, enough);
415	  const day = (n: number) => addDays(today, Math.max(0, Math.ceil(n)));
416	  const runsOut =
417	    run && run.value.median <= CREDIT_HORIZON_DAYS
418	      ? {
419	          median: day(run.value.median),
420	          early: day(run.value.p10),
421	          late: day(run.value.p90),
422	        }
423	      : null;
424	  return {
425	    month: month.value,
426	    spentMicros: input.spentMicros,
427	    availableMicros: input.availableMicros,
428	    runsOut,
429	    outlastsMonth: !runsOut || runsOut.early > monthEnd,
430	    monthEnd,
431	    source: month.source,
432	  };
433	}
434	
435	/** Credit worth a quiet line in the editor: the median runs out within a week. */
436	export function creditNeedsNotice(f: CreditForecast | null, now: number): boolean {
437	  if (!f?.runsOut) return false;
438	  return f.runsOut.median <= addDays(localDay(now), 7);
439	}
