441	/* ── Formatting ─────────────────────────────────────────────────── */
442	
443	const roundWords = (n: number) =>
444	  n >= 1_000 ? Math.round(n / 50) * 50 : n >= 200 ? Math.round(n / 10) * 10 : Math.round(n);
445	
446	export function formatWords(n: number, locale?: string): string {
447	  return new Intl.NumberFormat(locale).format(roundWords(Math.max(0, n)));
448	}
449	
450	export function formatWordRange(i: Interval, locale?: string): string {
451	  const lo = formatWords(i.p10, locale);
452	  const hi = formatWords(i.p90, locale);
453	  return lo === hi ? lo : `${lo}–${hi}`;
454	}
455	
456	export function formatDay(day: string, locale?: string): string {
457	  return new Intl.DateTimeFormat(locale, { month: "short", day: "numeric" }).format(
458	    new Date(dayToTime(day)),
459	  );
460	}
461	
462	/** "Nov 8 – 25" in one month, "Oct 29 – Nov 4" across two. */
463	export function formatDayRange(early: string, late: string, locale?: string): string {
464	  if (early === late) return formatDay(early, locale);
465	  const a = new Date(dayToTime(early));
466	  const b = new Date(dayToTime(late));
467	  const sameMonth = a.getMonth() === b.getMonth() && a.getFullYear() === b.getFullYear();
468	  const end = sameMonth
469	    ? new Intl.DateTimeFormat(locale, { day: "numeric" }).format(b)
470	    : formatDay(late, locale);
471	  return `${formatDay(early, locale)} – ${end}`;
472	}
473	
474	export function formatUsd(micros: number, locale?: string): string {
475	  return new Intl.NumberFormat(locale, {
476	    style: "currency",
477	    currency: "USD",
478	    minimumFractionDigits: 2,
479	    maximumFractionDigits: 2,
480	  }).format(micros / 1e6);
481	}

