 53	
 54	export function rhythmRequest(
 55	  input: PauseInput,
 56	  baseline: RhythmEstimate,
 57	): ExtractionRequest {
 58	  const seconds = (values: number[]) =>
 59	    values
 60	      .slice(-24)
 61	      .map((ms) => Math.round(ms / 1000))
 62	      .join(",");
 63	  return {
 64	    state: [
 65	      `run_seconds_csv=${seconds(input.profile.runs)}`,
 66	      `pause_seconds_csv=${seconds(input.profile.pauses)}`,
 67	      `current_run_seconds=${input.runSeconds}`,
 68	      `focus_bout_seconds=${(input.lastKeyAt - input.runStartedAt) / 1000}`,
 69	      `seconds_since_last_key=${(input.now - input.lastKeyAt) / 1000}`,
 70	      `key_events_per_10_seconds_oldest_first=${rhythmCounts(input.samples, input.now).join(",")}`,
 71	      `delete_ratio=${input.deleteRatio}`,
 72	      `reference_exit_pause_seconds=${input.exitPauseMs / 1000}`,
 73	      `local_hour=${new Date(input.now).getHours()}`,
 74	      `empirical_remaining_seconds=${JSON.stringify(baseline)}`,
 75	    ].join("\n"),
 76	    fields: {
 77	      focus_remaining: estimate(
 78	        "Seconds from now to the last keystroke of this rhythmic focus bout. The reference bout ends when a pause reaches the writer's exit pause, regardless of UI decisions. Shorter gaps can resume. Cadence-run history is an empirical baseline, not cognitive focus evidence.",
 79	        { min: 1, max: 3600, unit: "seconds", log: true, step: 1 },
 80	      ),
 81	      pause_length: estimate(
 82	        "Remaining seconds from now until the next keystroke, conditional on the pause already observed. Compare the empirical remaining-pause interval.",
 83	        { min: 1, max: 600, unit: "seconds", log: true, step: 1 },
 84	      ),
 85	    },
 86	  };
 87	}
