 89	export class FlowRhythmEstimator {
 90	  log: RhythmPrediction[] = [];
 91	  private pause: RhythmPrediction | null = null;
 92	  private model: RhythmPrediction | null = null;
 93	  private serial = 0;
 94	  private calls = 0;
 95	  private attemptedPauses = new Set<number>();
 96	  private unavailable = false;
 97	  private timeout: ReturnType<typeof setTimeout> | undefined;
 98	  private current: (() => boolean) | undefined;
 99	  constructor(private changed: () => void = () => {}) {}
100	
101	  begin(input: PauseInput): void {
102	    if (this.pause?.lastKeyAt === input.lastKeyAt) return;
103	    this.invalidate();
104	    const token = this.serial;
105	    this.current = input.current;
106	    const baseline = rhythmBaseline(
107	      input.profile,
108	      input.runSeconds,
109	      (input.now - input.lastKeyAt) / 1000,
110	    );
111	    this.pause = {
112	      id: `${input.runStartedAt}:${input.lastKeyAt}`,
113	      source: "baseline",
114	      at: input.now,
115	      lastKeyAt: input.lastKeyAt,
116	      runStartedAt: input.runStartedAt,
117	      runSeconds: input.runSeconds,
118	      pauseSeconds: (input.now - input.lastKeyAt) / 1000,
119	      estimate: baseline,
120	    };
121	    this.log = appendPrediction(this.log, this.pause);
122	    this.changed();
123	    if (
124	      !baseline.focus ||
125	      !baseline.pause ||
126	      !input.ask ||
127	      this.unavailable ||
128	      this.calls >= MAX_RHYTHM_CALLS_PER_SESSION ||
129	      this.attemptedPauses.has(input.lastKeyAt) ||
130	      extractionWait(input.now)
131	    )
132	      return;
133	    this.calls++;
134	    this.attemptedPauses.add(input.lastKeyAt);
135	    spendExtraction(input.now);
136	    const prediction = this.pause;
137	    let expired = false;
138	    this.timeout = setTimeout(() => {
139	      expired = true;
140	      backOffExtraction();
141	    }, ESTIMATE_TIMEOUT_MS);
142	    const fresh = () =>
143	      !expired &&
144	      token === this.serial &&
145	      this.pause === prediction &&
146	      Date.now() >= input.now &&
147	      Date.now() - input.now <= ESTIMATE_TIMEOUT_MS &&
148	      (input.current?.() ?? true);
149	    void Promise.resolve()
150	      .then(() => input.ask!(rhythmRequest(input, baseline)))
151	      .then((result) => {
152	        if (!result.ok || result.truncated) {
153	          if (
154	            fresh() &&
155	            (result.error === "unconfigured" || result.error === "signed out")
156	          )
157	            this.unavailable = true;
158	          backOffExtraction();
159	          return;
160	        }
161	        if (!fresh()) return;
162	        const focusAnswer = result.answers?.focus_remaining;
163	        const pauseAnswer = result.answers?.pause_length;
164	        const focus = interval(focusAnswer);
165	        const pause = interval(pauseAnswer);
166	        if (
167	          focusAnswer?.type !== "estimate" ||
168	          pauseAnswer?.type !== "estimate" ||
169	          typeof focusAnswer.value !== "number" ||
170	          typeof pauseAnswer.value !== "number" ||
171	          !Number.isFinite(focusAnswer.value) ||
172	          !Number.isFinite(pauseAnswer.value) ||
173	          (focusAnswer.p_null ?? 0) > 0.5 ||
174	          (pauseAnswer.p_null ?? 0) > 0.5 ||
175	          !validInterval(focus) ||
176	          !validInterval(pause) ||
177	          focus.p10 < 1 ||
178	          focus.p90 > 3600 ||
179	          pause.p10 < 1 ||
180	          pause.p90 > 600
181	        ) {
182	          backOffExtraction();
183	          return;
184	        }
185	        // Both sources forecast from the same instant, for a paired comparison.
186	        this.model = {
187	          ...prediction,
188	          source: "clairic",
189	          estimate: { focus, pause },
190	        };
191	        this.log = appendPrediction(this.log, this.model);
192	        this.changed();
193	      })
194	      .catch(() => {
195	        backOffExtraction();
196	      })
197	      .finally(() => {
198	        if (token === this.serial) clearTimeout(this.timeout);
199	      });
200	  }
201	
202	  selected(): RhythmPrediction | null {
203	    return this.model && (this.current?.() ?? true) && trustClairic(this.log)
204	      ? this.model
205	      : this.pause;
206	  }
207	  decision(now: number, exitPauseMs: number) {
208	    const p = this.selected();
209	    return p
210	      ? pauseDecision(p.estimate, exitPauseMs, Math.max(0, (now - p.at) / 1000))
211	      : "timer";
212	  }
213	  breakPrediction(folioId: string): RhythmBreak | null {
214	    const p = this.selected();
215	    return p && predictedBreak(p.estimate.pause, p.pauseSeconds)
216	      ? {
217	          folioId,
218	          at: p.at,
219	          lastKeyAt: p.lastKeyAt,
220	          pause: p.estimate.pause,
221	          pauseSeconds: p.pauseSeconds,
222	        }
223	      : null;
224	  }
225	  finishRun(runStartedAt: number, lastKeyAt: number): void {
226	    this.log = resolveRun(this.log, runStartedAt, lastKeyAt);
227	    // A model response may still arrive for this pause; resolve it too.
228	    if (this.pause?.runStartedAt === runStartedAt)
229	      this.pause.actualFocus = Math.max(0, (lastKeyAt - this.pause.at) / 1000);
230	    this.changed();
231	  }
232	  key(lastKeyAt: number, now: number): void {
233	    this.log = resolvePause(this.log, lastKeyAt, now);
234	    this.invalidate();
235	    this.changed();
236	  }
237	  invalidate(): void {
238	    this.serial++;
239	    clearTimeout(this.timeout);
240	    this.pause = this.model = null;
241	    this.current = undefined;
242	  }
243	}
  1	/** Bounded on-device evidence. Outcomes never depend on the prediction's gate. */
  2	import type { Interval } from "./extraction";
  3	import { validInterval, type RhythmEstimate } from "./flow-rhythm";
  4	
  5	export const PREDICTION_LOG_KEY = "flow-rhythm-predictions";
  6	export const MAX_PREDICTIONS = 240;
  7	export const MIN_CALIBRATION_PAIRS = 20;
  8	const CALIBRATION_WINDOW = 50;
  9	export type PredictionSource = "baseline" | "clairic";
 10	export interface RhythmPrediction {
 11	  id: string;
 12	  source: PredictionSource;
 13	  at: number;
 14	  /** Observed focus bout, closed by the ordinary exit pause, never the model. */
 15	  runStartedAt: number;
 16	  lastKeyAt: number;
 17	  runSeconds: number;
 18	  pauseSeconds: number;
 19	  estimate: RhythmEstimate;
 20	  actualFocus?: number;
 21	  actualPause?: number;
 22	}
 23	
 24	export function normalizePredictions(value: unknown): RhythmPrediction[] {
 25	  if (!Array.isArray(value)) return [];
 26	  return value
 27	    .filter((p): p is RhythmPrediction => {
 28	      if (!p || typeof p !== "object") return false;
 29	      return (
 30	        typeof p.id === "string" &&
 31	        ["baseline", "clairic"].includes(p.source) &&
 32	        [p.at, p.runStartedAt, p.lastKeyAt, p.runSeconds, p.pauseSeconds].every(
 33	          (n) => typeof n === "number" && Number.isFinite(n) && n >= 0,
 34	        ) &&
 35	        p.estimate &&
 36	        (p.estimate.focus === null || validInterval(p.estimate.focus)) &&
 37	        (p.estimate.pause === null || validInterval(p.estimate.pause)) &&
 38	        [p.actualFocus, p.actualPause].every(
 39	          (n) =>
 40	            n === undefined ||
 41	            (typeof n === "number" && Number.isFinite(n) && n >= 0),
 42	        )
 43	      );
 44	    })
 45	    .slice(-MAX_PREDICTIONS);
 46	}
 47	
 48	export function appendPrediction(
 49	  log: readonly RhythmPrediction[],
 50	  prediction: RhythmPrediction,
 51	): RhythmPrediction[] {
 52	  return [...log, prediction].slice(-MAX_PREDICTIONS);
 53	}
 54	
 55	export function resolveRun(
 56	  log: readonly RhythmPrediction[],
 57	  runStartedAt: number,
 58	  lastKeyAt: number,
 59	): RhythmPrediction[] {
 60	  return log.map((p) =>
 61	    p.runStartedAt === runStartedAt && p.actualFocus === undefined
 62	      ? { ...p, actualFocus: Math.max(0, (lastKeyAt - p.at) / 1000) }
 63	      : p,
 64	  );
 65	}
 66	
 67	export function resolvePause(
 68	  log: readonly RhythmPrediction[],
 69	  lastKeyAt: number,
 70	  nextKeyAt: number,
 71	): RhythmPrediction[] {
 72	  return log.map((p) =>
 73	    p.lastKeyAt === lastKeyAt && p.actualPause === undefined
 74	      ? { ...p, actualPause: Math.max(0, (nextKeyAt - p.at) / 1000) }
 75	      : p,
 76	  );
 77	}
 78	
 79	export function pinball(actual: number, predicted: number, q: number): number {
 80	  const error = actual - predicted;
 81	  return error * (error >= 0 ? q : q - 1);
 82	}
 83	
 84	export function intervalScore(actual: number, interval: Interval): number {
 85	  return (
 86	    interval.p90 -
 87	    interval.p10 +
 88	    10 * Math.max(0, interval.p10 - actual) +
 89	    10 * Math.max(0, actual - interval.p90)
 90	  );
 91	}
 92	
 93	export interface Calibration {
 94	  count: number;
 95	  coverage: number;
 96	  pinball: number;
 97	  intervalScore: number;
 98	}
 99	
100	export function calibration(
101	  log: readonly RhythmPrediction[],
102	  source: PredictionSource,
103	  target: "focus" | "pause",
104	): Calibration {
105	  const resolved = log
106	    .filter(
107	      (p) =>
108	        p.source === source &&
109	        validInterval(p.estimate[target]) &&
110	        (target === "focus" ? p.actualFocus : p.actualPause) !== undefined,
111	    )
112	    .slice(-CALIBRATION_WINDOW);
113	  let covered = 0,
114	    loss = 0,
115	    score = 0;
116	  for (const p of resolved) {
117	    const interval = p.estimate[target]!;
118	    const actual = (target === "focus" ? p.actualFocus : p.actualPause)!;
119	    covered += Number(actual >= interval.p10 && actual <= interval.p90);
120	    loss +=
121	      (pinball(actual, interval.p10, 0.1) +
122	        pinball(actual, interval.median, 0.5) +
123	        pinball(actual, interval.p90, 0.9)) /
124	      3;
125	    score += intervalScore(actual, interval);
126	  }
127	  const count = resolved.length;
128	  return {
129	    count,
130	    coverage: count ? covered / count : 0,
131	    pinball: count ? loss / count : Infinity,
132	    intervalScore: count ? score / count : Infinity,
133	  };
134	}
135	
136	/** Compare the same pauses, never two sources' unrelated samples. */
137	export function trustClairic(log: readonly RhythmPrediction[]): boolean {
138	  const complete = (p: RhythmPrediction) =>
139	    validInterval(p.estimate.focus) &&
140	    validInterval(p.estimate.pause) &&
141	    p.actualFocus !== undefined &&
142	    p.actualPause !== undefined;
143	  const baselines = new Map(
144	    log
145	      .filter((p) => p.source === "baseline" && complete(p))
146	      .map((p) => [p.id, p]),
147	  );
148	  const models = log
149	    .filter((p) => {
150	      const baseline = baselines.get(p.id);
151	      return (
152	        p.source === "clairic" &&
153	        complete(p) &&
154	        baseline &&
155	        baseline.at === p.at &&
156	        baseline.lastKeyAt === p.lastKeyAt &&
157	        baseline.runStartedAt === p.runStartedAt &&
158	        baseline.actualFocus === p.actualFocus &&
159	        baseline.actualPause === p.actualPause
160	      );
161	    })
162	    .slice(-CALIBRATION_WINDOW);
163	  if (models.length < MIN_CALIBRATION_PAIRS) return false;
164	  const paired = [...models, ...models.map((p) => baselines.get(p.id)!)];
165	  return (["focus", "pause"] as const).every((target) => {
166	    const model = calibration(paired, "clairic", target);
167	    const baseline = calibration(paired, "baseline", target);
168	    return (
169	      model.coverage >= 0.7 &&
170	      model.coverage <= 0.9 &&
171	      model.pinball < baseline.pinball &&
172	      model.intervalScore < baseline.intervalScore
173	    );
174	  });
175	}

