  1	/**
  2	 * The deterministic half of every forecast Twyne shows.
  3	 *
  4	 * Clairic's forecasts drift toward the average, and with a week of history
  5	 * there is no average worth drifting toward. So each surface is computed here
  6	 * first, from the writer's own numbers, and the model is only allowed to
  7	 * replace it when there is enough history and it lands near this answer
  8	 * (`preferForecast`). Everything is an 80% interval: median, p10, p90.
  9	 */
 10	import type { Interval } from "./extraction";
 11	
 12	/** z for the 10th/90th percentile of a normal. */
 13	const Z80 = 1.2816;
 14	
 15	export function quantile(values: readonly number[], q: number): number {
 16	  if (!values.length) return 0;
 17	  const sorted = [...values].sort((a, b) => a - b);
 18	  const index = Math.min(sorted.length - 1, Math.max(0, (sorted.length - 1) * q));
 19	  const lo = Math.floor(index);
 20	  const hi = Math.ceil(index);
 21	  return sorted[lo] + (sorted[hi] - sorted[lo]) * (index - lo);
 22	}
 23	
 24	export function meanAndSd(values: readonly number[]): { mean: number; sd: number } {
 25	  if (!values.length) return { mean: 0, sd: 0 };
 26	  const mean = values.reduce((a, b) => a + b, 0) / values.length;
 27	  if (values.length < 2) return { mean, sd: 0 };
 28	  const variance =
 29	    values.reduce((sum, v) => sum + (v - mean) ** 2, 0) / (values.length - 1);
 30	  return { mean, sd: Math.sqrt(variance) };
 31	}
 32	
 33	/* ── Today's pace ─────────────────────────────────────────────── */
 34	
 35	export interface PaceHistoryDay {
 36	  /** 0 = Sunday, as `Date#getDay`. */
 37	  weekday: number;
 38	  /** Net words per local hour. */
 39	  hours: number[];
 40	}
 41	
 42	export const PACE_MIN_DAYS = 3;
 43	
 44	/**
 45	 * Words the writer will finish today with, from what they usually add after
 46	 * this point in the day.
 47	 *
 48	 * Conditioned on writing days only: the line only shows once today has
 49	 * begun, so the question is "on days like this, how much more came?". Uses
 50	 * the same weekday when there are three of them, every writing day
 51	 * otherwise. The interval is the empirical spread of those days' remainders.
 52	 */
 53	export function paceBaseline(input: {
 54	  history: readonly PaceHistoryDay[];
 55	  weekday: number;
 56	  /** Fractional local hour now, e.g. 14.5 at half past two. */
 57	  hourNow: number;
 58	  wordsSoFar: number;
 59	}): (Interval & { days: number }) | null {
 60	  const writing = input.history.filter((d) =>
 61	    d.hours.some((n) => n > 0),
 62	  );
 63	  if (writing.length < PACE_MIN_DAYS) return null;
 64	  const sameDay = writing.filter((d) => d.weekday === input.weekday);
 65	  const pool = sameDay.length >= PACE_MIN_DAYS ? sameDay : writing;
 66	  const hour = Math.min(23, Math.max(0, Math.floor(input.hourNow)));
 67	  const left = 1 - (input.hourNow - hour);
 68	  const remainders = pool.map((d) => {
 69	    let rest = Math.max(0, d.hours[hour] ?? 0) * left;
 70	    for (let h = hour + 1; h < 24; h++) rest += Math.max(0, d.hours[h] ?? 0);
 71	    return rest;
 72	  });
 73	  const base = Math.max(0, input.wordsSoFar);
 74	  return {
 75	    median: base + quantile(remainders, 0.5),
 76	    p10: base + quantile(remainders, 0.1),
 77	    p90: base + quantile(remainders, 0.9),
 78	    days: pool.length,
 79	  };
 80	}
