 32	export const RHYTHM_BREAK_EVENT = "twyne:rhythm-break";
 33	export const ESTIMATE_TIMEOUT_MS = 1_500;
 34	export interface RhythmBreak {
 35	  folioId: string;
 36	  at: number;
 37	  lastKeyAt: number;
 38	  pause: RhythmEstimate["pause"];
 39	  pauseSeconds: number;
 40	}
 41	interface PauseInput {
 42	  now: number;
 43	  lastKeyAt: number;
 44	  runStartedAt: number;
 45	  runSeconds: number;
 46	  deleteRatio: number;
 47	  exitPauseMs: number;
 48	  samples: readonly KeySample[];
 49	  profile: FlowProfile;
 50	  ask?: (request: ExtractionRequest) => Promise<ExtractionResult>;
 51	  current?: () => boolean;
 52	}
