  1	/** Rhythm forecasts contain seconds and counts only; no manuscript state. */
  2	import { quantile, type FlowProfile } from "./flow-profile";
  3	import type { Interval } from "./extraction";
  4	import type { FlowMode, KeySample } from "./flow-state";
  5	
  6	export const MIN_RHYTHM_HISTORY = 8;
  7	export type PauseDecision = "hold" | "release" | "timer";
  8	export interface RhythmEstimate {
  9	  focus: Interval | null;
 10	  pause: Interval | null;
 11	}
 12	
 13	/** Remaining seconds, conditional on having already lasted `elapsedSeconds`. */
 14	export function remainingQuantiles(
 15	  durationsMs: readonly number[],
 16	  elapsedSeconds: number,
 17	  minimum = MIN_RHYTHM_HISTORY,
 18	): Interval | null {
 19	  if (!Number.isFinite(elapsedSeconds) || elapsedSeconds < 0) return null;
 20	  const remaining = durationsMs
 21	    .filter((ms) => Number.isFinite(ms) && ms / 1000 > elapsedSeconds)
 22	    .map((ms) => ms / 1000 - elapsedSeconds);
 23	  if (remaining.length < Math.max(1, minimum)) return null;
 24	  return {
 25	    p10: quantile(remaining, 0.1)!,
 26	    median: quantile(remaining, 0.5)!,
 27	    p90: quantile(remaining, 0.9)!,
 28	  };
 29	}
 30	
 31	export function rhythmBaseline(
 32	  profile: FlowProfile,
 33	  runSeconds: number,
 34	  pauseSeconds: number,
 35	): RhythmEstimate {
 36	  return {
 37	    focus: remainingQuantiles(profile.runs, runSeconds),
 38	    pause: remainingQuantiles(profile.pauses, pauseSeconds),
 39	  };
 40	}
 41	
 42	export function validInterval(value: Interval | null): value is Interval {
 43	  return (
 44	    !!value &&
 45	    [value.p10, value.median, value.p90].every(
 46	      (n) => Number.isFinite(n) && n >= 0,
 47	    ) &&
 48	    value.p10 <= value.median &&
 49	    value.median <= value.p90
 50	  );
 51	}
 52	
 53	/** Both estimates are remaining durations at the time they were made. */
 54	export function pauseDecision(
 55	  estimate: RhythmEstimate,
 56	  exitPauseMs: number,
 57	  ageSeconds = 0,
 58	): PauseDecision {
 59	  const { focus, pause } = estimate;
 60	  if (!validInterval(focus) || !validInterval(pause)) return "timer";
 61	  if (focus.p90 - ageSeconds < 10) return "release";
 62	  if (focus.p10 - ageSeconds >= 30 && pause.median < exitPauseMs / 1000)
 63	    return "hold";
 64	  return "timer";
 65	}
 66	
 67	/** An estimate of the whole pause, including the time already observed. */
 68	export function predictedBreak(
 69	  pause: Interval | null,
 70	  elapsedAtPrediction: number,
 71	  minimumSeconds = 60,
 72	): boolean {
 73	  return (
 74	    Number.isFinite(elapsedAtPrediction) &&
 75	    elapsedAtPrediction >= 0 &&
 76	    validInterval(pause) &&
 77	    pause.p10 + elapsedAtPrediction >= minimumSeconds
 78	  );
 79	}
 80	
 81	export function rhythmCounts(
 82	  samples: readonly KeySample[],
 83	  now: number,
 84	): number[] {
 85	  const bins = Array<number>(6).fill(0);
 86	  for (const sample of samples) {
 87	    const age = now - sample.at;
 88	    if (age >= 0 && age < 60_000) bins[5 - Math.floor(age / 10_000)]++;
 89	  }
 90	  return bins;
 91	}
 92	
 93	/** Existing cards may stay in settling; costly, little-used kinds can wait. */
 94	export function skipFragileKind(
 95	  mode: FlowMode,
 96	  weight: number,
 97	  costSeconds: number | null,
 98	): boolean {
 99	  return (
100	    mode === "settling" &&
101	    weight < 0.8 &&
102	    costSeconds !== null &&
103	    costSeconds >= 30
104	  );
105	}
106	
107	/** Least-used hours first. No preference until at least an hour was observed. */
108	export function awayHours(profile: FlowProfile, top = 3): number[] {
109	  const hours = profile.hours.map((minutes, hour) => ({
110	    hour,
111	    minutes: Math.max(0, minutes),
112	  }));
113	  const total = hours.reduce((sum, h) => sum + h.minutes, 0);
114	  if (total < 60 || hours.some((h) => !Number.isFinite(h.minutes))) return [];
115	  return hours
116	    .filter((h) => h.minutes < total / 24)
117	    .sort((a, b) => a.minutes - b.minutes || a.hour - b.hour)
118	    .slice(0, Math.max(0, top))
119	    .map((h) => h.hour);
120	}

