    }
    setFlowAttribute(mode);
    if (
      next.pauseMs <= t.gapMs &&
      (mode === "settling" || mode === "flow") &&
      next.deleteRatio <= t.maxDeleteRatio &&
      next.activeRatio >= t.minActiveRatio
