     1	/**
     2	 * Words written, by local day and hour — the history the pace and finish
     3	 * forecasts read.
     4	 *
     5	 * The flow profile already knows *minutes* per hour; forecasts need *words*,
     6	 * and per draft, so this is its own small ledger. Only counts, never text,
     7	 * and on this device only (one meta record, capped at `MAX_DAYS`).
     8	 *
     9	 * Words are net: a cut is negative. A single observation that moves the
    10	 * count by more than `MAX_STEP` is treated as a load, paste or folio switch
    11	 * and re-baselines instead of counting as writing.
    12	 */
    13	import { loadMetaFromIdb, saveMetaToIdb } from "./idb";
    14	
    15	export const PACE_LEDGER_KEY = "writing-pace:v1";
    16	const MAX_DAYS = 60;
    17	const MAX_STEP = 1_500;
    18	
    19	export interface PaceDay {
    20	  /** Net words written in each local hour. */
    21	  hours: number[];
    22	  /** Each draft's word count at its first and latest observation that day. */
    23	  folios: Record<string, { start: number; end: number }>;
    24	}
    25	
    26	export interface PaceLedger {
    27	  version: 1;
    28	  /** Keyed by local calendar day, `YYYY-MM-DD`. */
    29	  days: Record<string, PaceDay>;
    30	  /** Latest count seen per draft, carried across days. */
    31	  last: Record<string, number>;
    32	}
    33	
    34	export function emptyLedger(): PaceLedger {
    35	  return { version: 1, days: {}, last: {} };
    36	}
    37	
    38	const pad = (n: number) => String(n).padStart(2, "0");
    39	
    40	/** Local calendar day for a timestamp. */
    41	export function localDay(at: number): string {
    42	  const d = new Date(at);
    43	  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
    44	}
    45	
    46	/** Midday on a local day key, so DST never pushes it into a neighbour. */
    47	export function dayToTime(day: string): number {
    48	  const [y, m, d] = day.split("-").map(Number);
    49	  return new Date(y, m - 1, d, 12).getTime();
    50	}
    51	
    52	export function addDays(day: string, n: number): string {
    53	  const d = new Date(dayToTime(day));
    54	  d.setDate(d.getDate() + n);
    55	  return localDay(d.getTime());
    56	}
    57	
    58	export function normalizeLedger(value: unknown): PaceLedger {
    59	  if (!value || typeof value !== "object") return emptyLedger();
    60	  const raw = value as Partial<PaceLedger>;
    61	  const days: Record<string, PaceDay> = {};
    62	  for (const [key, day] of Object.entries(raw.days ?? {})) {
    63	    if (!/^\d{4}-\d{2}-\d{2}$/.test(key) || !day) continue;
    64	    const hours = Array.isArray(day.hours) ? day.hours : [];
    65	    days[key] = {
    66	      hours: Array.from({ length: 24 }, (_, h) =>
    67	        Number.isFinite(hours[h]) ? hours[h] : 0,
    68	      ),
    69	      folios: day.folios && typeof day.folios === "object" ? day.folios : {},
    70	    };
    71	  }
    72	  return {
    73	    version: 1,
    74	    days,
    75	    last: raw.last && typeof raw.last === "object" ? raw.last : {},
    76	  };
    77	}
    78	
    79	/** Fold one word-count observation of a draft into the ledger. */
    80	export function observeWordCount(
    81	  ledger: PaceLedger,
    82	  folioId: string,
    83	  wordCount: number,
    84	  at: number,
    85	): PaceLedger {
    86	  if (!folioId || !Number.isFinite(wordCount) || wordCount < 0) return ledger;
    87	  const key = localDay(at);
    88	  const previous = ledger.last[folioId];
    89	  const day: PaceDay = ledger.days[key]
