    95	  const jump = previous === undefined ? 0 : wordCount - previous;
    96	  const delta = Math.abs(jump) > MAX_STEP ? 0 : jump;
    97	  const folio = day.folios[folioId];
    98	  // The day starts from where the draft stood, minus anything just counted;
    99	  // a rejected jump moves the start with it, so it never reads as writing.
   100	  day.folios[folioId] = {
   101	    start: (folio?.start ?? wordCount - delta) + (folio ? jump - delta : 0),
   102	    end: wordCount,
   103	  };
