   106	  const days = { ...ledger.days, [key]: day };
   107	  const keys = Object.keys(days).sort();
   108	  for (const old of keys.slice(0, Math.max(0, keys.length - MAX_DAYS)))
   109	    delete days[old];
   110	  return { version: 1, days, last: { ...ledger.last, [folioId]: wordCount } };
   111	}
   112	
   113	/** Net words across every draft on a day. */
