   120	 * Days with no record count as zero — rest days are part of the pace.
   121	 */
   122	export function folioDailyGains(
   123	  ledger: PaceLedger,
   124	  folioId: string,
   125	  today: string,
   126	  span: number,
   127	): { gains: number[]; observedDays: number } {
   128	  const seen = Object.keys(ledger.days)
   129	    .filter((key) => ledger.days[key].folios[folioId])
   130	    .sort();
   131	  if (!seen.length) return { gains: [], observedDays: 0 };
   132	  const first = seen[0];
   133	  const gains: number[] = [];
   134	  for (let i = span - 1; i >= 0; i--) {
   135	    const key = addDays(today, -i);
   136	    if (key < first) continue;
   137	    const f = ledger.days[key]?.folios[folioId];
   138	    gains.push(f ? f.end - f.start : 0);
   139	  }
   140	  return { gains, observedDays: gains.length };
   141	}
   142	
   143	let queue: Promise<unknown> = Promise.resolve();
