   145	export async function loadPaceLedger(): Promise<PaceLedger> {
   146	  return normalizeLedger(await loadMetaFromIdb(PACE_LEDGER_KEY));
   147	}
   148	
   149	/** Serialised so two quick saves cannot read the same stale ledger. */
   150	export function recordWordCount(
   151	  folioId: string,
   152	  wordCount: number,
   153	  at = Date.now(),
   154	): Promise<PaceLedger> {
   155	  const next = queue.then(async () => {
   156	    const ledger = observeWordCount(
   157	      await loadPaceLedger(),
   158	      folioId,
   159	      wordCount,
   160	      at,
   161	    );
