    l = observeWordCount(l, "f", 350, at("2026-10-18", 10));
    const { gains, observedDays } = folioDailyGains(l, "f", "2026-10-20", 28);
    expect(gains).toEqual([200, 0, 0, 50, 0, 0]);
    expect(observedDays).toBe(6);
  });
});

