 129	export function quantile(values: readonly number[], q: number): number | null {
 130	  if (!values.length) return null;
 131	  const sorted = [...values].sort((a, b) => a - b);
 132	  const index = Math.min(
 133	    sorted.length - 1,
 134	    Math.max(0, (sorted.length - 1) * q),
 135	  );
 136	  const lo = Math.floor(index);
 137	  const hi = Math.ceil(index);
 138	  return sorted[lo] + (sorted[hi] - sorted[lo]) * (index - lo);
 139	}
 140	
 141	const clamp = (v: number, lo: number, hi: number) =>
 142	  Math.min(hi, Math.max(lo, v));
