 171	/** The writer's usual hours, strongest first — for the inspector. */
 172	export function writingHours(p: FlowProfile, top = 3): number[] {
 173	  return p.hours
 174	    .map((minutes, hour) => ({ minutes, hour }))
 175	    .filter((h) => h.minutes > 0)
 176	    .sort((a, b) => b.minutes - a.minutes)
 177	    .slice(0, top)
 178	    .map((h) => h.hour);
 179	}
