  23	export interface KeySample {
  24	  at: number;
  25	  inserted: number;
  26	  deleted: number;
  27	}
  28	
  29	export interface FlowThresholds {
  30	  /** Longest gap between keys that still counts as one run. */
  31	  gapMs: number;
  32	  /** Run length before the chrome starts to dim. */
  33	  settleMs: number;
  34	  /** Run length before the page goes quiet. */
  35	  flowMs: number;
  36	  /** A pause this long, after churn, reads as stuck. */
  37	  stuckPauseMs: number;
  38	  /** A pause this long ends flow. */
  39	  exitPauseMs: number;
  40	  /** No keys for this long reads as away. */
  41	  awayMs: number;
  42	  /** Share of characters taken back that still counts as steady. */
  43	  maxDeleteRatio: number;
  44	  /** Share of the run's seconds that carried a key. */
  45	  minActiveRatio: number;
  46	}
  47	
  48	export const DEFAULT_THRESHOLDS: FlowThresholds = {
  49	  gapMs: 4_000,
  50	  settleMs: 30_000,
  51	  flowMs: 90_000,
  52	  stuckPauseMs: 18_000,
  53	  exitPauseMs: 25_000,
  54	  awayMs: 180_000,
  55	  maxDeleteRatio: 0.3,
  56	  minActiveRatio: 0.45,
