     1	/**
     2	 * What Twyne learns about how this writer works.
     3	 *
     4	 * Only rhythms and reactions, never words: how long their runs last, how long
     5	 * they pause between them, how long it takes them to settle, what hours they
     6	 * write, and which kinds of margin help they use versus wave away. Stored on
     7	 * this device only.
     8	 *
     9	 * Two things read it:
    10	 *   - `thresholdsFor` fits the flow detector to the writer. Someone who
    11	 *     habitually pauses 20 seconds to think is not stuck at 20 seconds.
    12	 *   - `kindWeight` ranks margin items. A kind the writer keeps dismissing
    13	 *     sinks; one they open rises. Laplace-smoothed, so it starts neutral and
    14	 *     no single click swings it.
    15	 */
    16	import { DEFAULT_THRESHOLDS, type FlowThresholds } from "./flow-state";
    17	
    18	export type ItemOutcome = "shown" | "engaged" | "dismissed";
    19	
    20	export interface KindStats {
    21	  shown: number;
    22	  engaged: number;
    23	  dismissed: number;
    24	}
    25	
    26	export interface FlowProfile {
    27	  version: 1;
    28	  /** Pauses between runs, ms; most recent last. */
    29	  pauses: number[];
    30	  /** Run lengths, ms. */
    31	  runs: number[];
    32	  /** Run length at the moment flow was confirmed, ms. */
    33	  flowEntries: number[];
    34	  /** Minutes written in each hour of the day, local time. */
    35	  hours: number[];
    36	  kinds: Record<string, KindStats>;
    37	  /** Times the writer switched automatic focus off by hand. */
    38	  overrides: number;
    39	  updatedAt: number;
    40	}
    41	
    42	const MAX_SAMPLES = 240;
    43	
    44	export function emptyProfile(): FlowProfile {
    45	  return {
    46	    version: 1,
    47	    pauses: [],
    48	    runs: [],
    49	    flowEntries: [],
    50	    hours: Array.from({ length: 24 }, () => 0),
    51	    kinds: {},
    52	    overrides: 0,
    53	    updatedAt: 0,
    54	  };
    55	}
    56	
    57	export function normalizeProfile(value: unknown): FlowProfile {
    58	  const base = emptyProfile();
    59	  if (!value || typeof value !== "object") return base;
    60	  const raw = value as Partial<FlowProfile>;
    61	  const numbers = (list: unknown) =>
    62	    Array.isArray(list)
    63	      ? list.filter((n): n is number => typeof n === "number" && isFinite(n))
    64	      : [];
    65	  const hours = numbers(raw.hours);
    66	  return {
    67	    version: 1,
    68	    pauses: numbers(raw.pauses).slice(-MAX_SAMPLES),
    69	    runs: numbers(raw.runs).slice(-MAX_SAMPLES),
    70	    flowEntries: numbers(raw.flowEntries).slice(-MAX_SAMPLES),
    71	    hours: hours.length === 24 ? hours : base.hours,
    72	    kinds: raw.kinds && typeof raw.kinds === "object" ? raw.kinds : {},
    73	    overrides: typeof raw.overrides === "number" ? raw.overrides : 0,
    74	    updatedAt: typeof raw.updatedAt === "number" ? raw.updatedAt : 0,
    75	  };
    76	}
    77	
    78	const push = (list: number[], value: number) =>
    79	  [...list, Math.round(value)].slice(-MAX_SAMPLES);
