    87	  if (ms < 1_500 || ms > 10 * 60_000) return p;
    88	  return { ...p, pauses: push(p.pauses, ms), updatedAt: now };
    89	}
    90	
    91	export function recordRun(
    92	  p: FlowProfile,
    93	  ms: number,
    94	  now: number,
    95	  hour = new Date(now).getHours(),
    96	): FlowProfile {
    97	  if (ms < 5_000) return p;
    98	  const hours = [...p.hours];
    99	  hours[hour] = (hours[hour] ?? 0) + ms / 60_000;
   100	  return { ...p, runs: push(p.runs, ms), hours, updatedAt: now };
   101	}
   102	
   103	export function recordFlowEntry(
   104	  p: FlowProfile,
   105	  runMs: number,
   106	  now: number,
   107	): FlowProfile {
   108	  return { ...p, flowEntries: push(p.flowEntries, runMs), updatedAt: now };
   109	}
   110	
   111	export function recordOverride(p: FlowProfile, now: number): FlowProfile {
   112	  return { ...p, overrides: p.overrides + 1, updatedAt: now };
   113	}
   114	
   115	export function recordItem(
   116	  p: FlowProfile,
   117	  kind: string,
   118	  outcome: ItemOutcome,
   119	  now: number,
   120	): FlowProfile {
   121	  const stats = p.kinds[kind] ?? { shown: 0, engaged: 0, dismissed: 0 };
