   123	    ...p,
   124	    kinds: { ...p.kinds, [kind]: { ...stats, [outcome]: stats[outcome] + 1 } },
   125	    updatedAt: now,
   126	  };
   127	}
   128	
   129	export function quantile(values: readonly number[], q: number): number | null {
   130	  if (!values.length) return null;
   131	  const sorted = [...values].sort((a, b) => a - b);
   132	  const index = Math.min(
   133	    sorted.length - 1,
   134	    Math.max(0, (sorted.length - 1) * q),
   135	  );
   136	  const lo = Math.floor(index);
   137	  const hi = Math.ceil(index);
   138	  return sorted[lo] + (sorted[hi] - sorted[lo]) * (index - lo);
   139	}
   140	
   141	const clamp = (v: number, lo: number, hi: number) =>
   142	  Math.min(hi, Math.max(lo, v));
   143	
   144	/**
   145	 * Fit the detector to the writer. Needs a dozen pauses before it trusts
   146	 * them; until then the defaults hold.
   147	 */
   148	export function thresholdsFor(p: FlowProfile): FlowThresholds {
   149	  const t = { ...DEFAULT_THRESHOLDS };
   150	  if (p.pauses.length >= 12) {
   151	    const typical = quantile(p.pauses, 0.75)!;
   152	    const long = quantile(p.pauses, 0.9)!;
   153	    t.stuckPauseMs = clamp(typical * 2, 12_000, 60_000);
   154	    t.exitPauseMs = clamp(long * 1.5, 15_000, 45_000);
   155	  }
   156	  if (p.flowEntries.length >= 5) {
   157	    t.flowMs = clamp(quantile(p.flowEntries, 0.5)!, 60_000, 240_000);
