   159	  }
   160	  return t;
   161	}
   162	
   163	/** 0.2..1.8 — how much this writer uses help of this kind. Neutral at 1. */
   164	export function kindWeight(p: FlowProfile, kind: string): number {
   165	  const s = p.kinds[kind];
   166	  if (!s) return 1;
   167	  const rate = (s.engaged + 1) / (s.engaged + s.dismissed + 2);
