   169	}
   170	
   171	/** The writer's usual hours, strongest first — for the inspector. */
   172	export function writingHours(p: FlowProfile, top = 3): number[] {
   173	  return p.hours
   174	    .map((minutes, hour) => ({ minutes, hour }))
   175	    .filter((h) => h.minutes > 0)
   176	    .sort((a, b) => b.minutes - a.minutes)
   177	    .slice(0, top)
   178	    .map((h) => h.hour);
   179	}
     1	/**
     2	 * Reading flow from the rhythm of the keys.
     3	 *
     4	 * Nothing here looks at the words — only at when they arrive and how many are
     5	 * taken back. Five readings:
     6	 *
     7	 *   away      no keys for minutes; nothing should change around the page
     8	 *   working   ordinary writing: pauses, rereads, small cuts
     9	 *   settling  a steady run has begun; the chrome starts to dim
    10	 *   flow      the run has held; the room goes quiet and the page stands alone
    11	 *   stuck     a long pause after cutting and circling — help may land now
    12	 *
    13	 * The readings are sticky on purpose. Entering flow takes a sustained run;
    14	 * leaving it takes a real pause (or the writer reaching for the room), never
    15	 * a single deletion or a glance away. A rewrite inside flow is still flow.
    16	 *
    17	 * Thresholds are not constants: `thresholdsFor` in `flow-profile.ts` derives
    18	 * them from how this writer actually pauses. Pure — `now` is passed in.
    19	 */
    20	
    21	export type FlowMode = "away" | "working" | "settling" | "flow" | "stuck";
    22	
    23	export interface KeySample {
    24	  at: number;
    25	  inserted: number;
    26	  deleted: number;
    27	}
    28	
    29	export interface FlowThresholds {
    30	  /** Longest gap between keys that still counts as one run. */
    31	  gapMs: number;
    32	  /** Run length before the chrome starts to dim. */
    33	  settleMs: number;
    34	  /** Run length before the page goes quiet. */
    35	  flowMs: number;
    36	  /** A pause this long, after churn, reads as stuck. */
    37	  stuckPauseMs: number;
    38	  /** A pause this long ends flow. */
    39	  exitPauseMs: number;
    40	  /** No keys for this long reads as away. */
    41	  awayMs: number;
    42	  /** Share of characters taken back that still counts as steady. */
    43	  maxDeleteRatio: number;
    44	  /** Share of the run's seconds that carried a key. */
    45	  minActiveRatio: number;
    46	}
    47	
    48	export const DEFAULT_THRESHOLDS: FlowThresholds = {
    49	  gapMs: 4_000,
    50	  settleMs: 30_000,
    51	  flowMs: 90_000,
    52	  stuckPauseMs: 18_000,
    53	  exitPauseMs: 25_000,
    54	  awayMs: 180_000,
    55	  maxDeleteRatio: 0.3,
    56	  minActiveRatio: 0.45,
    57	};
    58	
    59	export interface FlowContext {
    60	  /** 0..1 from `readStruggle` for the paragraph under the cursor. */
    61	  struggle?: number;
    62	  /** A fresh, calibrated rhythm interval; absence preserves the usual timer. */
    63	  pauseDecision?: "hold" | "release" | "timer";
    64	  /** The writer has held the pointer over the room (margins, masthead). */
    65	  reaching?: boolean;
    66	}
    67	
    68	export interface FlowReading {
    69	  mode: FlowMode;
    70	  /** Length of the current (or last) run, ms. */
    71	  runMs: number;
    72	  /** Time since the last key, ms. */
    73	  pauseMs: number;
    74	  activeRatio: number;
    75	  deleteRatio: number;
    76	  /** Words a minute across the run, at five characters a word. */
    77	  wpm: number;
    78	  /** Deletions over the last minute of writing, as a share of all edits. */
    79	  recentChurn: number;
    80	  reason: string;
    81	}
    82	
    83	/** Keep only what `readFlow` can use; call on every sample. */
    84	export function trimSamples(
    85	  samples: KeySample[],
    86	  now: number,
    87	  keepMs = 10 * 60_000,
    88	): KeySample[] {
    89	  const cutoff = now - keepMs;
    90	  let start = 0;
    91	  while (start < samples.length && samples[start].at < cutoff) start++;
    92	  return start ? samples.slice(start) : samples;
    93	}
